use std::process::ExitCode;

use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    x_min: f32,
    x_max: f32,
    y_min: f32,
    y_max: f32,
}

@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read_write> out: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    let j = gid.y;
    if (i >= p.width || j >= p.height) {
        return;
    }

    let cx = p.x_min + (f32(i) + 0.5) * (p.x_max - p.x_min) / f32(p.width);
    let cy = p.y_min + (f32(j) + 0.5) * (p.y_max - p.y_min) / f32(p.height);

    var zx = 0.0;
    var zy = 0.0;
    var n = 0u;
    loop {
        if (n >= p.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let nzx = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = nzx;
        n = n + 1u;
    }

    out[j * p.width + i] = n;
}
"#;

#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    x_min: f32,
    x_max: f32,
    y_min: f32,
    y_max: f32,
}

struct Job {
    width: u32,
    height: u32,
    limit: u32,
    x_min: f64,
    x_max: f64,
    y_min: f64,
    y_max: f64,
}

fn parse_job(text: &str) -> Result<Job, String> {
    let tokens: Vec<&str> = text.split_whitespace().collect();
    if tokens.len() != 7 {
        return Err(format!("expected 7 numbers, found {}", tokens.len()));
    }
    let int = |s: &str| s.parse::<u32>().map_err(|e| format!("bad integer {s:?}: {e}"));
    let num = |s: &str| s.parse::<f64>().map_err(|e| format!("bad number {s:?}: {e}"));

    let job = Job {
        width: int(tokens[0])?,
        height: int(tokens[1])?,
        limit: int(tokens[2])?,
        x_min: num(tokens[3])?,
        x_max: num(tokens[4])?,
        y_min: num(tokens[5])?,
        y_max: num(tokens[6])?,
    };
    if !(1..=1024).contains(&job.width) || !(1..=1024).contains(&job.height) {
        return Err("width and height must be between 1 and 1024".into());
    }
    if !(1..=1000).contains(&job.limit) {
        return Err("limit must be between 1 and 1000".into());
    }
    if !(job.x_min < job.x_max) || !(job.y_min < job.y_max) {
        return Err("bounds must satisfy x_min < x_max and y_min < y_max".into());
    }
    Ok(job)
}

/// Runs the escape-time kernel on the GPU and returns one escape time per
/// point, row-major.
fn escape_times(job: &Job) -> Result<Vec<u32>, String> {
    pollster::block_on(async {
        let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
        let adapter = instance
            .request_adapter(&wgpu::RequestAdapterOptions {
                power_preference: wgpu::PowerPreference::HighPerformance,
                ..Default::default()
            })
            .await
            .map_err(|e| format!("no GPU adapter: {e}"))?;
        let (device, queue) = adapter
            .request_device(&wgpu::DeviceDescriptor::default())
            .await
            .map_err(|e| format!("cannot create GPU device: {e}"))?;

        let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("escape"),
            source: wgpu::ShaderSource::Wgsl(SHADER.into()),
        });
        let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("escape"),
            layout: None,
            module: &module,
            entry_point: Some("main"),
            compilation_options: Default::default(),
            cache: None,
        });

        let params = Params {
            width: job.width,
            height: job.height,
            limit: job.limit,
            x_min: job.x_min as f32,
            x_max: job.x_max as f32,
            y_min: job.y_min as f32,
            y_max: job.y_max as f32,
        };
        let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("params"),
            contents: bytemuck::bytes_of(&params),
            usage: wgpu::BufferUsages::UNIFORM,
        });

        let count = u64::from(job.width) * u64::from(job.height);
        let size = count * std::mem::size_of::<u32>() as u64;
        let out_buf = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("out"),
            size,
            usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
            mapped_at_creation: false,
        });
        let read_buf = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("readback"),
            size,
            usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });

        let layout = pipeline.get_bind_group_layout(0);
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("escape"),
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: params_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: out_buf.as_entire_binding(),
                },
            ],
        });

        let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
            label: Some("escape"),
        });
        {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: Some("escape"),
                timestamp_writes: None,
            });
            pass.set_pipeline(&pipeline);
            pass.set_bind_group(0, &bind_group, &[]);
